mapper.select:
SELECT COSTUME_ID, COSTUME_NAME, PART, PRICE_RATE, IMAGE_PATH AS LOOK
FROM COSTUME
WHERE COSTUME_ID = #{costumeId}

mapper.update:
UPDATE LIFE
SET ASSETS = ASSETS - #{price}
WHERE LIFE_ID = #{lifeId} AND STATUS = 'PLAYING' AND ASSETS >= #{price}

UPDATE LIFE_COSTUME
SET IS_EQUIPPED = #{equipped}
WHERE LIFE_ID = #{lifeId} AND COSTUME_ID = #{costumeId}
